import assert from 'node:assert/strict';
import { Session } from './src/session.js';

let calls = 0;
const offlineHost = { queryFn({ signal }) { calls++; assert.equal(signal.aborted, false); return 'found'; }, timers: { schedule() {} } };
const offline = new Session(offlineHost, { online: false });
const first = offline.subscribe('central', { networkMode: 'online' });
assert.equal(offline.snapshot('central').fetchStatus, 'paused');
offline.unsubscribe(first);
offline.online(true);
await Promise.resolve();
assert.equal(calls, 0, 'an abandoned, never-started offline query must not start after reconnect');
const second = offline.subscribe('central', { networkMode: 'online' });
assert.equal(calls, 0, 'paused continuation is deferred');
await Promise.resolve();
assert.equal(calls, 1);
await Promise.resolve();
assert.deepEqual(offline.snapshot('central'), { status: 'success', fetchStatus: 'idle', data: 'found' });
offline.unsubscribe(second);

let resolve;
const ongoing = new Session({ queryFn() { return new Promise(r => { resolve = r; }); }, timers: { schedule() {} } });
const handle = ongoing.subscribe('museum');
ongoing.unsubscribe(handle);
resolve('cached');
await Promise.resolve();
await Promise.resolve();
assert.deepEqual(ongoing.snapshot('museum'), { status: 'success', fetchStatus: 'idle', data: 'cached' });

let sharedCalls = 0;
const shared = new Session({ queryFn() { sharedCalls++; return 'shared'; }, timers: { schedule() {} } });
const one = shared.subscribe('river');
const two = shared.subscribe('river');
assert.equal(sharedCalls, 1);
await Promise.resolve();
shared.unsubscribe(one); shared.unsubscribe(two);
console.log('session regression checks passed');
NODE"

